package ca.brentzinck.fintracid;

import android.app.*; import android.content.*; import android.database.Cursor; import android.graphics.Typeface; import android.net.Uri; import android.os.Bundle; import android.provider.OpenableColumns; import android.view.*; import android.widget.*;
import androidx.documentfile.provider.DocumentFile; import org.json.JSONObject;
import java.io.*; import java.nio.charset.StandardCharsets; import java.text.SimpleDateFormat; import java.util.*; import java.util.concurrent.*;

public class MainActivity extends Activity {
 static final int FOLDER=1001,IMPORT=1002,CAMERA=1003,SCREENSHOT=1004; static final String PREFS="relay_capture_prefs",KEY_FOLDER="folder_uri",KEY_CATS="categories";
 static final List<String> SEEDED=Arrays.asList("FINTRAC ID","Client Document","Signed Page","Property / Problem","Utility / Statement","Receipt / Expense","General Capture"),TYPES=Arrays.asList("None","Person","Matter","Property","Organization","Other");
 final List<Item> items=new ArrayList<>(); final ExecutorService exec=Executors.newSingleThreadExecutor(); TextView status,staged;Spinner category,type;EditText entity,matter,note;Button secure;
 @Override public void onCreate(Bundle b){super.onCreate(b);build();recoverPending();receive(getIntent());state();} @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);receive(i);}
 void build(){int p=dp(20);ScrollView sc=new ScrollView(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(p,p,p,p);sc.addView(r);TextView t=new TextView(this);t.setText("Relay Capture");t.setTextSize(30);t.setTypeface(Typeface.DEFAULT_BOLD);r.addView(t);TextView sub=new TextView(this);sub.setText("Capture. Context. Secure handoff.");sub.setTextSize(16);sub.setPadding(0,dp(4),0,dp(16));r.addView(sub);status=new TextView(this);r.addView(status);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.addView(btn("Camera",v->startActivityForResult(new Intent(this,CaptureActivity.class),CAMERA)),weight());row.addView(btn("Screenshot",v->startActivityForResult(new Intent(this,ScreenshotActivity.class),SCREENSHOT)),weight());row.addView(btn("Import",v->chooseImport()),weight());r.addView(row);staged=new TextView(this);staged.setPadding(0,dp(12),0,dp(4));r.addView(staged);r.addView(btn("Review / remove staged items",v->review()));r.addView(label("Category"));LinearLayout cr=new LinearLayout(this);cr.setOrientation(LinearLayout.HORIZONTAL);category=new Spinner(this);refreshCats(null);cr.addView(category,weight());cr.addView(btn("+",v->addCat()),new LinearLayout.LayoutParams(dp(56),-2));cr.addView(btn("Edit",v->manageCats()),new LinearLayout.LayoutParams(dp(78),-2));r.addView(cr);r.addView(label("Entity type"));type=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,TYPES));r.addView(type);r.addView(label("Person / property / organization"));entity=edit("Optional entity name or identifier");r.addView(entity);r.addView(label("Matter / transaction / project"));matter=edit("Optional matter reference");r.addView(matter);r.addView(label("Note"));note=edit("Optional context");note.setMinLines(2);r.addView(note);secure=btn("Secure to Relay Intake",v->secure());r.addView(secure);r.addView(btn("Choose / change intake folder",v->chooseFolder()));setContentView(sc);}
 Button btn(String s,View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setOnClickListener(l);return b;}TextView label(String s){TextView v=new TextView(this);v.setText(s);v.setTypeface(Typeface.DEFAULT_BOLD);v.setPadding(0,dp(10),0,0);return v;}EditText edit(String h){EditText e=new EditText(this);e.setHint(h);return e;}LinearLayout.LayoutParams weight(){return new LinearLayout.LayoutParams(0,-2,1);}
 void receive(Intent in){if(in==null)return;String a=in.getAction();if(!Intent.ACTION_SEND.equals(a)&&!Intent.ACTION_SEND_MULTIPLE.equals(a))return;for(Uri u:uris(in))items.add(Item.uri(u,getName(u),"shared"));in.setAction(Intent.ACTION_MAIN);state();}
 void chooseImport(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/*","application/pdf"});i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT);}void chooseFolder(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);startActivityForResult(i,FOLDER);}
 @Override protected void onActivityResult(int rq,int rc,Intent d){super.onActivityResult(rq,rc,d);if(rc!=RESULT_OK||d==null)return;if(rq==FOLDER&&d.getData()!=null){Uri u=d.getData();int f=d.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);try{getContentResolver().takePersistableUriPermission(u,f);getSharedPreferences(PREFS,MODE_PRIVATE).edit().putString(KEY_FOLDER,u.toString()).apply();}catch(Exception x){toast("Could not preserve folder access.");}state();return;}if(rq==IMPORT){if(d.getClipData()!=null)for(int i=0;i<d.getClipData().getItemCount();i++){Uri u=d.getClipData().getItemAt(i).getUri();items.add(Item.uri(u,getName(u),"imported"));}else if(d.getData()!=null){Uri u=d.getData();items.add(Item.uri(u,getName(u),"imported"));}state();return;}if(rq==CAMERA){String p=d.getStringExtra(CaptureActivity.EXTRA_CAPTURE_PATH);if(p!=null)items.add(Item.file(new File(p),"camera"));state();return;}if(rq==SCREENSHOT){String p=d.getStringExtra(ScreenshotActivity.EXTRA_CAPTURE_PATH);if(p!=null)items.add(Item.file(new File(p),"screenshot"));state();}}
 void review(){if(items.isEmpty()){toast("Nothing staged yet.");return;}String[] a=new String[items.size()];for(int i=0;i<a.length;i++)a[i]=(i+1)+". "+items.get(i).display();new AlertDialog.Builder(this).setTitle("Tap an item to remove it").setItems(a,(d,w)->{Item it=items.remove(w);if(it.file!=null)it.file.delete();state();}).setNeutralButton("Clear all",(d,w)->{for(Item it:items)if(it.file!=null)it.file.delete();items.clear();state();}).setPositiveButton("Done",null).show();}
 void secure(){if(items.isEmpty()){toast("Capture or import something first.");return;}Uri fu=folder();if(fu==null){toast("Choose Relay Intake first.");chooseFolder();return;}String cat=String.valueOf(category.getSelectedItem()),typ=String.valueOf(type.getSelectedItem()),ent=entity.getText().toString().trim(),mat=matter.getText().toString().trim(),nt=note.getText().toString().trim(),cid=UUID.randomUUID().toString();long when=System.currentTimeMillis();secure.setEnabled(false);status.setText("TRANSFER IN PROGRESS");exec.execute(()->{String fail=null;int saved=0;try{DocumentFile f=DocumentFile.fromTreeUri(this,fu);if(f==null||!f.canWrite())throw new Exception("Relay Intake is not writable.");int seq=1;for(Item it:new ArrayList<>(items)){save(f,it,seq++,cid,cat,typ,ent,mat,nt,when);saved++;}}catch(Exception x){fail=x.getMessage();}int fs=saved;String ff=fail;runOnUiThread(()->{secure.setEnabled(true);if(ff==null){for(Item it:items)if(it.file!=null)it.file.delete();items.clear();state();status.setText("✓ SECURED · "+fs+(fs==1?" item":" items")+" saved. Local temporary copies removed.");}else{status.setText("LOCAL ONLY · Transfer failed. Private local captures retained for retry.");toast(ff);}});});}
 void save(DocumentFile folder,Item it,int seq,String cid,String cat,String typ,String ent,String mat,String nt,long secured)throws Exception{ContentResolver r=getContentResolver();String mime=it.file!=null?(it.file.getName().endsWith(".png")?"image/png":"image/jpeg"):r.getType(it.uri);if(mime==null)mime="application/octet-stream";String ex=ext(it.name,mime),date=new SimpleDateFormat("yyyy-MM-dd",Locale.CANADA).format(new Date()),anchor=!ent.isEmpty()?ent:(!mat.isEmpty()?mat:"Unassigned"),fn=safe(date+" - "+anchor+" - "+cat+" - "+seq)+ex;DocumentFile target=folder.createFile(mime,fn);if(target==null)throw new Exception("Could not create destination file.");long bytes=0;try(InputStream in=it.file!=null?new FileInputStream(it.file):r.openInputStream(it.uri);OutputStream out=r.openOutputStream(target.getUri(),"w")){if(in==null||out==null)throw new Exception("Could not open capture.");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){out.write(b,0,n);bytes+=n;}out.flush();}if(!target.exists()||(target.length()==0&&bytes>0))throw new Exception("Destination verification failed.");JSONObject j=new JSONObject();j.put("relay_schema_version",1);j.put("capture_id",cid);j.put("captured_at",it.created);j.put("secured_at",secured);j.put("source",it.source);j.put("category",cat);j.put("entity_type",typ);j.put("entity",ent);j.put("matter",mat);j.put("note",nt);j.put("original_name",it.name);j.put("app_version","1.0.0");j.put("mime_type",mime);j.put("file_name",fn);j.put("bytes_written",bytes);DocumentFile side=folder.createFile("application/json",fn+".json");if(side==null)throw new Exception("Could not create provenance sidecar.");try(OutputStream out=r.openOutputStream(side.getUri(),"w")){out.write(j.toString(2).getBytes(StandardCharsets.UTF_8));out.flush();}}
 void addCat(){EditText x=new EditText(this);x.setHint("New category");new AlertDialog.Builder(this).setTitle("Add category").setView(x).setPositiveButton("Add",(d,w)->{String v=x.getText().toString().trim();if(!v.isEmpty()){Set<String>s=custom();s.add(v);saveCats(s);refreshCats(v);}}).setNegativeButton("Cancel",null).show();}void manageCats(){List<String> all=cats();String[] a=all.toArray(new String[0]);new AlertDialog.Builder(this).setTitle("Edit or remove custom category").setItems(a,(d,w)->{String old=a[w];if(SEEDED.contains(old)){toast("Built-in categories remain available.");return;}EditText x=new EditText(this);x.setText(old);new AlertDialog.Builder(this).setTitle("Edit category").setView(x).setPositiveButton("Save",(dd,ww)->{String nv=x.getText().toString().trim();Set<String>s=custom();s.remove(old);if(!nv.isEmpty())s.add(nv);saveCats(s);refreshCats(nv);}).setNegativeButton("Remove",(dd,ww)->{Set<String>s=custom();s.remove(old);saveCats(s);refreshCats(null);}).show();}).setNegativeButton("Done",null).show();}
 Set<String> custom(){return new LinkedHashSet<>(getSharedPreferences(PREFS,MODE_PRIVATE).getStringSet(KEY_CATS,new LinkedHashSet<>()));}void saveCats(Set<String>s){getSharedPreferences(PREFS,MODE_PRIVATE).edit().putStringSet(KEY_CATS,s).apply();}List<String> cats(){LinkedHashSet<String>s=new LinkedHashSet<>(SEEDED);s.addAll(custom());return new ArrayList<>(s);}void refreshCats(String sel){List<String>a=cats();category.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,a));if(sel!=null&&a.indexOf(sel)>=0)category.setSelection(a.indexOf(sel));}
 void recoverPending(){File d=new File(getFilesDir(),"relay_pending");File[] fs=d.listFiles();if(fs!=null)for(File f:fs)if(f.isFile())items.add(Item.file(f,f.getName().startsWith("screenshot_")?"screenshot":"camera/recovered"));}void state(){if(staged!=null)staged.setText(items.isEmpty()?"Nothing staged.":items.size()+(items.size()==1?" item staged.":" items staged."));if(status!=null)status.setText(folder()==null?"LOCAL ONLY · Choose a Relay Intake folder before securing.":"Relay Intake configured. Pending local captures survive failed transfers.");if(secure!=null)secure.setEnabled(!items.isEmpty());}
 Uri folder(){String s=getSharedPreferences(PREFS,MODE_PRIVATE).getString(KEY_FOLDER,null);return s==null?null:Uri.parse(s);}List<Uri> uris(Intent i){List<Uri>o=new ArrayList<>();if(i.getClipData()!=null)for(int x=0;x<i.getClipData().getItemCount();x++){Uri u=i.getClipData().getItemAt(x).getUri();if(u!=null)o.add(u);}if(o.isEmpty()){Uri u=i.getParcelableExtra(Intent.EXTRA_STREAM);if(u!=null)o.add(u);}return o;}String getName(Uri u){try(Cursor c=getContentResolver().query(u,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}catch(Exception ignored){}return "capture";}String ext(String n,String m){if(n!=null&&n.contains(".")){String e=n.substring(n.lastIndexOf('.'));if(e.length()<8)return e;}if("application/pdf".equals(m))return ".pdf";if("image/png".equals(m))return ".png";return m.startsWith("image/")?".jpg":".bin";}String safe(String s){return s.replaceAll("[\\\\/:*?\"<>|]","_").trim();}void toast(String s){Toast.makeText(this,s==null?"Unknown error":s,Toast.LENGTH_LONG).show();}int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}@Override protected void onDestroy(){super.onDestroy();if(isFinishing())exec.shutdown();}
 static class Item{Uri uri;File file;String name,source;long created;static Item uri(Uri u,String n,String s){Item i=new Item();i.uri=u;i.name=n;i.source=s;i.created=System.currentTimeMillis();return i;}static Item file(File f,String s){Item i=new Item();i.file=f;i.name=f.getName();i.source=s;i.created=f.lastModified();return i;}String display(){return name+" · "+source;}}
}
